import React, { useState } from "react";
import axios from "axios";
import Swal from "sweetalert2";
import toast, { Toaster } from "react-hot-toast";
import "../styles/main.css";

export default function AdminManageFee() {
  const [admissionNo, setAdmissionNo] = useState("");
  const [data, setData] = useState(null);

  // same class logic as parent side
  const getFeeKeysForClass = (cls, allItems) => {
    const c = Number(cls);
    if (c >= 1 && c <= 5) return ["development", "transport"];
    if (c >= 6 && c <= 9) return ["tuition", "development", "transport"];
    const defaultKeys = ["exam", "tuition", "development"];

    // include admin-added items also
    const extra = Object.keys(allItems).filter(
      (k) => !defaultKeys.includes(k)
    );

    return [...defaultKeys, ...extra];
  };

  const fetchFee = async () => {
    if (!admissionNo.trim()) return toast.error("Enter admission number");
    try {
      const res = await axios.get(
        `http://localhost:5000/api/admin/fees/student/${admissionNo}`
      );

      if (res.data.success) {
        setData(res.data.data);
        toast.success("Student record loaded");
      } else toast.error("Record not found");
    } catch (e) {
      toast.error("Failed to load");
      console.log(e);
    }
  };

  // ADD FEE ITEM
  const addFeeItem = async () => {
    const { value: form } = await Swal.fire({
      title: "Add Fee Type",
      html: `
        <input id="key" class="swal2-input" placeholder="Key (e.g., sports)" />
        <input id="title" class="swal2-input" placeholder="Title (e.g., Sports Fee)" />
        <input id="amount" type="number" class="swal2-input" placeholder="Amount" />
      `,
      focusConfirm: false,
      preConfirm: () => {
        return {
          key: document.getElementById("key").value.trim(),
          title: document.getElementById("title").value.trim(),
          amount: Number(document.getElementById("amount").value),
        };
      },
      confirmButtonText: "Add",
      showCancelButton: true,
    });

    if (!form) return;

    if (!form.key || !form.title || !form.amount)
      return toast.error("All fields required");

    try {
      const res = await axios.post(
        "http://localhost:5000/api/admin/fees/addItem",
        {
          admissionNo,
          ...form,
        }
      );

      if (res.data.success) {
        toast.success("Added successfully");
        fetchFee();
      } else toast.error(res.data.error);
    } catch (err) {
      toast.error("Failed to add");
    }
  };

  // UPDATE FEE ITEM AMOUNT OR TITLE
  const editFeeItem = async (key, item) => {
    const { value: form } = await Swal.fire({
      title: "Edit Fee Type",
      html: `
        <input id="title" class="swal2-input" value="${item.title}" />
        <input id="amount" type="number" class="swal2-input" value="${item.amount}" />
      `,
      focusConfirm: false,
      preConfirm: () => {
        return {
          title: document.getElementById("title").value.trim(),
          amount: Number(document.getElementById("amount").value),
        };
      },
      confirmButtonText: "Update",
      showCancelButton: true,
    });

    if (!form) return;

    try {
      const res = await axios.put(
        "http://localhost:5000/api/admin/fees/updateItem",
        {
          admissionNo,
          key,
          ...form,
        }
      );

      if (res.data.success) {
        toast.success("Updated");
        fetchFee();
      } else toast.error(res.data.error);
    } catch (e) {
      toast.error("Update failed");
    }
  };

  // DELETE
  const deleteFeeItem = async (key) => {
    const ok = await Swal.fire({
      title: "Delete?",
      text: "This cannot be undone",
      icon: "warning",
      showCancelButton: true,
      confirmButtonText: "Yes, delete",
    });

    if (!ok.isConfirmed) return;

    try {
      const res = await axios.delete(
        "http://localhost:5000/api/admin/fees/deleteItem",
        {
          data: { admissionNo, key },
        }
      );

      if (res.data.success) {
        toast.success("Deleted");
        fetchFee();
      } else toast.error(res.data.error);
    } catch (e) {
      toast.error("Delete failed");
    }
  };

  const renderFeeTable = () => {
    if (!data) return null;

    const student = data.student;
    const items = data.fee?.items || {};
    const keys = getFeeKeysForClass(student.class, items);

    return (
      <div className="fee-card">
        <h3>Manage Fee — {student.studentName} (Class {student.class})</h3>

        <button className="primary-btn" onClick={addFeeItem}>
          + Add Fee Type
        </button>

        <table className="fee-table">
          <thead>
            <tr>
              <th>Key</th>
              <th>Title</th>
              <th>Amount</th>
              <th>Action</th>
            </tr>
          </thead>

          <tbody>
            {keys.map((k) => (
              <tr key={k}>
                <td>{k}</td>
                <td>{items[k]?.title}</td>
                <td>₹{items[k]?.amount?.toLocaleString()}</td>

                <td>
                  <button
                    className="secondary-btn"
                    onClick={() => editFeeItem(k, items[k])}
                  >
                    Edit
                  </button>

                  <button
                    className="danger-btn"
                    onClick={() => deleteFeeItem(k)}
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  };

  return (
    <div className="fee-page">
      <Toaster />
      <div className="fee-container">
        <h2>🛠 Manage Student Fee Structure</h2>

        <div className="search-box">
          <input
            type="text"
            placeholder="Enter Admission No."
            value={admissionNo}
            onChange={(e) => setAdmissionNo(e.target.value)}
          />
          <button onClick={fetchFee}>Search</button>
        </div>

        {renderFeeTable()}
      </div>
    </div>
  );
}
